P=Path(__file__).resolve().parent;T=P/'platform-tools';H=lambda b:hashlib.sha256(b).hexdigest();env={'PATH':os.pathsep.join([str(T/'rust/bin'),str(T/'llvm/bin'),'/usr/bin','/bin']),'RUSTUP_HOME':str(P/'capability-rustup')};cmds=[];specs={};cfgs={};maps={}
