(P/'capability.rs').write_text('#![no_std]\npub fn probe() -> u64 { 1 }\n');run([str(T/'rust/bin/rustc'),'--crate-type=lib','--target=sbf-solana-solana',str(P/'capability.rs'),'-o',str(P/'capability.rlib')])
(P/'header-probe.ll').write_text('define i64 @probe(i64 %x) {\n %y = add i64 %x, 1\n ret i64 %y\n}\n');run([str(T/'llvm/bin/llc'),'-march=sbf','-mcpu=generic','-filetype=obj',str(P/'header-probe.ll'),'-o',str(P/'v148-generic.o')]);b=(P/'v148-generic.o').read_bytes();assert(struct.unpack_from('<H',b,18)[0],struct.unpack_from('<I',b,48)[0])==(263,0)
version=run([str(T/'rust/bin/rustc'),'--version','--verbose']);out={'stock_target':'sbf-solana-solana','legacy_target_works':True,'intrinsic_features':s['features'],'overrides':False,'header':[263,0],'alias_specs_equal':True,'alias_sysroot_maps_equal':maps['sbf-solana-solana']==maps['sbpf-solana-solana'],'sysroot_maps':maps,'cfg':cfgs,'rustc_version':version,'commands':cmds,'program_builds':0};(P/'target-preflight.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items()if k not in['commands','sysroot_maps','cfg']},indent=2))
